import { defineConfig } from 'vite-plus'

// Files generated by tools. They are never formatted or linted by hand. drizzle-kit writes the
// snapshots and the journal of migrations/meta, and reads them back as it wrote them.
const generated = [
  '**/dist/**',
  '**/.wrangler/**',
  '**/worker-configuration.d.ts',
  '**/migrations/meta/**',
  // scripts/sync-starter.ts writes it from templates/starter, which is formatted and linted.
  'packages/create-hollware/template/**',
]

// Test fixtures whose bytes matter: the formatter would rewrite the Markdown under test.
const fixtures = ['tests/fixtures/content/**']

export default defineConfig({
  staged: {
    '*': 'vp check --fix',
  },
  fmt: {
    semi: false,
    singleQuote: true,
    ignorePatterns: [...generated, ...fixtures],
  },
  lint: {
    plugins: ['typescript', 'unicorn', 'oxc', 'import', 'node'],
    jsPlugins: [{ name: 'vite-plus', specifier: 'vite-plus/oxlint-plugin' }],
    options: { typeAware: true, typeCheck: true },
    ignorePatterns: generated,
    rules: {
      'vite-plus/prefer-vite-plus-imports': 'error',
      // Workers cancel promises nobody awaits, so a dropped promise is a silent bug.
      'typescript/no-floating-promises': 'error',
      'typescript/no-misused-promises': 'error',
      'typescript/no-explicit-any': 'error',
    },
    overrides: [
      {
        // Packages take configuration as arguments; process.env would be a hidden input.
        files: ['packages/*/src/**'],
        rules: { 'node/no-process-env': 'error' },
      },
      {
        // Tests build typed values through helpers instead of casting with `as`.
        files: ['**/*.test.ts', 'tests/**'],
        rules: {
          'typescript/consistent-type-assertions': ['error', { assertionStyle: 'never' }],
        },
      },
      {
        // Tests that run inside workerd use @cloudflare/vitest-plugin, which
        // needs the real `vitest` imports rather than `vite-plus/test`.
        files: ['**/*.workerd.test.ts'],
        rules: { 'vite-plus/prefer-vite-plus-imports': 'off' },
      },
    ],
  },
  test: {
    // Each package folder is a project (its own vite.config.ts, if any, applies). A package
    // whose tests also run in workerd adds vitest.workerd.config.ts (core, ADR-018).
    // Worker apps expose their test configs as vitest.config.ts or vitest.*.config.ts.
    projects: [
      'packages/*',
      'packages/*/vitest.*.config.ts',
      'apps/*/vitest.config.ts',
      'apps/*/vitest.*.config.ts',
      'templates/*/vitest.config.ts',
      'examples/*/vitest.config.ts',
      {
        test: {
          name: 'repo',
          include: ['scripts/**/*.test.ts', 'tests/**/*.test.ts'],
          exclude: ['tests/acceptance/**', 'tests/conformance/**', 'tests/e2e/**'],
          environment: 'node',
        },
      },
    ],
  },
  run: {
    cache: { scripts: false, tasks: true },
    tasks: {
      // The pre-commit hook runs check:commit; CI runs check:push, and test:conformance,
      // test:acceptance and e2e:admin in jobs of their own.
      'check:commit': { command: 'vp check', cache: false },
      // The Markdown pipeline's budget: the p95 CPU time of a write of the 2,027-word fixture.
      bench: {
        command:
          "vp test bench --project '@hollware/core (bench)' packages/core/bench/markdown.bench.ts",
        cache: false,
      },
      // The size budget of the Hollware Worker, built minified (budgets.json), and its startup and
      // write cost, which are logged and have no ceiling.
      'check:budgets': { command: 'node scripts/check-budgets.ts', cache: false },
      // The acceptance suites of the stages, against the built playground and example site
      // (PLAN.md lists what each criterion checks).
      'test:acceptance': {
        command: 'vp test run --config tests/acceptance/vitest.config.ts',
        cache: false,
      },
      // The end-to-end tests of the admin (v0.3): Chromium with a virtual passkey against the
      // built playground under `wrangler dev`, with axe on every page (tests/e2e).
      'e2e:admin': {
        command: 'playwright test -c tests/e2e/playwright.config.ts',
        cache: false,
      },
      // The MCP conformance run (ADR-022): the tests of its runner, then the suite against
      // `wrangler dev` of tests/conformance/worker, through the token proxy, for both revisions.
      'test:conformance': {
        command: [
          'vp test run --config tests/conformance/vitest.config.ts',
          'node tests/conformance/run.ts',
        ],
        cache: false,
      },
      'check:push': {
        command: [
          'vp check',
          'vp test',
          'vp run bench',
          'vp run -r build',
          'vp run check:budgets',
          'node scripts/check-bins.ts',
          'vp run -r publint',
          'vp run -r types:check',
        ],
        cache: false,
      },
    },
  },
})
